import json,csv,collections,hashlib,subprocess
from pathlib import Path
def read(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def write(p,v):Path(p).write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
cs=read('corpus.json');refs=[read(p) for p in sorted(Path('reference').glob('*.json'))]
assert len(refs)==len(cs)==len({c['key'] for c in cs})==len({r['key'] for r in refs})
assert {r['key'] for r in refs}=={c['key'] for c in cs}
rr={r['key']:r for r in refs};ao=read('app-original.json');ap=read('app-patched.json');orig={a['key']:a for a in ao};patched={a['key']:a for a in ap}
o=read('results-original.json');p=read('results-patched.json');fo=read('focused-original.json');fp=read('focused-patched.json');ds=read('dataset-ledger.json')
for result in [o,p]:assert result['configuration_count']==len(cs) and sum(result['reference_statuses'].values())==len(cs)
write('reference.json',refs)
manifest=read('source-manifest.json');commit=manifest['commit']
rows=[];refusals=[];splits=[]
for c in cs:
    r=rr[c['key']];row={k:c[k] for k in ['key','package','dataset','outcome','measure','subset','model','recipe']}
    row.update(k=len(c['rows']),reference_status=r['status'],reason=r.get('reason',''),input_sha256=hashlib.sha256(json.dumps(c['rows'],sort_keys=True,separators=(',',':')).encode()).hexdigest())
    rows.append(row)
    for variant,data in [('original',orig),('patched',patched)]:
        a=data[c['key']];state=a.get('state') or {}
        if r['status']!='ok' or state.get('status')=='refused' or a['error']:
            refusals.append(dict(key=c['key'],variant=variant,expected_status=r['status'],expected_reason=r.get('reason',''),app_status=state.get('status','ok'),app_reason=state.get('reason',''),execution_error=a['error'] or ''))
    if r['status']=='ok':
        n0={n['comparison'] for n in orig[c['key']]['state'].get('nodeSplit',[])};n1={n['comparison'] for n in patched[c['key']]['state'].get('nodeSplit',[])}
        for s in r['nodeSplit']+r['split_exclusions']:
            splits.append(dict(key=c['key'],comparison=s['comparison'],reference_status='tested' if 'diff' in s else 'not_testable',reason=s.get('reason',''),original_present=s['comparison'] in n0,patched_present=s['comparison'] in n1))
for file,data in [('configuration-ledger.csv',rows),('refusal-ledger.csv',refusals),('split-ledger.csv',splits)]:
    with Path(file).open('w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
statuses=collections.Counter(r['status'] for r in refs);reasons=collections.Counter(r.get('reason') for r in refs if r['status']=='refused')
category=lambda x:{cat:{'checks':sum(s['checks'] for s in x['quantities'].values() if s['category']==cat),'passed':sum(s['passed'] for s in x['quantities'].values() if s['category']==cat)} for cat in sorted({s['category'] for s in x['quantities'].values()})}
write('results.json',{'commit':commit,'configuration_count':len(cs),'dataset_count':len(ds),'included_datasets':sum(d['configurations']>0 for d in ds),'original':{'passed':o['passed'],'checks':o['checks'],'categories':category(o)},'patched':{'passed':p['passed'],'checks':p['checks'],'categories':category(p)},'focused_original':{'passed':fo['passed'],'checks':fo['checks']},'focused_patched':{'passed':fp['passed'],'checks':fp['checks']},'reference_statuses':dict(statuses),'refusal_reasons':dict(reasons),'browser_evidence':False,'execution':'Node shipped inline engine + renderer + shared exporter via minimal DOM adapter','multiarm_parity':False})
text=(Path('app-original/nma-inconsistency/index.html').read_text(encoding='utf-8')).splitlines()
anchors={name:next(i+1 for i,line in enumerate(text) if needle in line) for name,needle in {'normal_p':'function pz(','split_connectivity':'const fit = fitNMA(others','no_loop_dbt':'if (designs.length <= cons.nBasic)','stale_results':'if (rows.length < 3) return;','parser':'const parts = l.split','pair_key':'pairs.add([r.A, r.B].sort().join','prototype_keys':'const estimates = {}','plot_domain':'const allMeans = ns.flatMap','bus_metadata':'ta.value = rows.map','undefined_export':'dbt: { Q: g.Q, df: g.df, p: g.p }'}.items()}
write('source-locations.json',anchors)
L=[f'# NMA inconsistency validation', '',f'Source commit: `{commit}`. Source files were copied without editing the checkout. Proposed app-only changes are in [fix.patch](fix.patch). No commit or push was made.', '',f'Original: **{o["passed"]}/{o["checks"]} checks pass**. Patched: **{p["passed"]}/{p["checks"]} checks pass**. Focused checks, counted separately: **{fo["passed"]}/{fo["checks"]}** original and **{fp["passed"]}/{fp["checks"]}** patched.', '',
'These totals include numerical, coverage, export, generated-markup and input-support checks. **Multi-arm refusals are not numerical parity passes. Browser rendering was not validated.** The different original/patched denominators reflect invalid/extra original splits and their emitted plot/text elements; the configuration and reference keys are identical.', '',
'## Coverage', '',f'{len(ds)} installed datasets were enumerated programmatically (13 netmeta and 114 metadat). {sum(d["configurations"]>0 for d in ds)} datasets supplied {len(cs)} configurations: 180 each for FE, DL and PM; 336 full-input and 204 explicitly labeled two-arm-only subset configurations. Inputs range from {min(len(c["rows"]) for c in cs)} to {max(len(c["rows"]) for c in cs)} contrasts. No upper cap or numerical truncation was imposed.', '',
'All documented network datasets in the installed netmeta/metadat documentation are included, together with additional explicit-treatment star networks. Package aliases remain separate candidates. [dataset-ledger.csv](dataset-ledger.csv) records every inclusion/exclusion and links its installed documentation; [construction-attempts.json](construction-attempts.json) records every recipe and warning, with no unresolved construction errors. [configuration-ledger.csv](configuration-ledger.csv) supplies unique keys, source recipes, input hashes and statuses. [row-exclusions.json](row-exclusions.json) records invalid pairwise inputs, package omissions and 16 Lopez studies with repeated identical treatment-arm labels whose standardized change scores were not aggregated under an invented assumption.', '',
'The corpus uses stored effects where provided; otherwise meta::pairwise or metafor::escalc constructs contrasts from documented arm outcomes. Binary arms use OR and RR, continuous raw arms MD and SMD, dietary-fat rates IRR, and the Lopez documented arm-change contrasts use diff1-diff2 and sqrt(se1²+se2²). Zero cells receive 0.5 only when required; all-zero binary studies are retained when the selected construction allows finite estimates. Distinct endpoints are separate recipes. Both engines consume the same serialized effects and SEs; SE-squared is the variance. Seventeen significant digits preserve binary64 inputs. Study identifiers are retained; multi-arm or repeated-study rows are never relabeled as independent trials.', '',
f'Reference/support statuses: `{dict(statuses)}`. Reasons: `{dict(reasons)}`. All refusals and original/patched responses are in [refusal-ledger.csv](refusal-ledger.csv). The R reference applies an explicit input-support gate before numerical fitting; matching that gate establishes refusal behavior only. Full native multi-arm numerical validation is outside this engine’s supported scope. Two-arm subsets remove whole identified multi-arm studies and are separate configurations, not replacements for the full input.', '',
'## Page contract and reference', '',
'The shipped page accepts A, B, effect and SE contrasts, treats every row as independent, and offers FE, generalized DL and generalized PM. It estimates a single τ² from consistency-model residuals; this is not a within-design heterogeneity estimate. The default is FE. It uses a normal 95% quantile of 1.959963984540054. There is no treatment/reference selector, confidence-level selector, other τ² estimator, Knapp–Hartung option, or study-count cap. Fewer than three accepted contrasts originally return silently; malformed numeric rows are silently filtered. The patch clears and reports refusals, accepts an optional study-ID column, and refuses multi-arm/repeated-study data and disconnected networks.', '',
'Node splitting removes all direct rows for a pair, fits the remaining network at the full-network τ², pools the direct rows at that same τ², and forms direct minus indirect with SE sqrt(SEdirect²+SEindirect²), z and two-sided normal p. For independent two-arm studies this matches netmeta back-calculation, and the fixed-τ split underlying SIDE/SIDDE. It is not a multi-arm SIDDE implementation. All signed quantities use lexically sorted A vs B; R’s reversed comparison names are explicitly sign-converted, never compared by absolute effect. Exact graph reachability determines which pairs have an independent indirect path. [split-ledger.csv](split-ledger.csv) records every tested or untestable pair.', '',
'The global statistic compares consistency and per-pair design models using the same weights. FE is compared to the Between designs row of netmeta::decomp.design; DL/PM use Q.inc.random.preset with tau.preset equal to the consistency-model τ. This differs from decomp.design’s default random test, which estimates τ within designs. A network without loops has Q=0, df=0 and undefined p; it cannot be labeled evidence of consistency.', '',
'R was 4.6.0; netmeta 3.7.0, meta 8.5.0, metadat 1.6.0, metafor 5.2.1 and jsonlite 2.0.0. Every R log prints .libPaths() and these versions. Portable library placeholders replace machine paths in logs. Startup locale warnings were captured. Installed help and source snapshots are in documentation/.', '',
'netmeta supports DL/ML/REML, not PM. The PM oracle therefore calls the installed metafor .QE.func with the **uncentered** outcome vector and the network contrast design, then stats::uniroot for Q(τ²)=k-p, and passes sqrt(τ²) into netmeta. Its bracket doubles from max(1,var(effect)); tolerance is .Machine$double.eps^0.75, maxiter=1000. The installed rma.uni centers outcomes internally even for this no-intercept design, so direct rma(...,method="PM",intercept=FALSE) was diagnosed and rejected as the oracle. [diagnose_pm.log](diagnose_pm.log) and documentation/PM-QE-source.txt document this reference-side correction. No R-package code was patched.', '',
'The original PM app solver uses 60 bisections and an absolute 1e-10 interval cutoff; the patch uses 100 and 1e-13*max(1,mid). Estimates, SEs, Q and τ² use relative abs(app-ref)/max(1,abs(ref)) ≤1e-9 for FE/DL and ≤1e-6 for PM-derived quantities. P-values always use 1e-9 absolute. Counts, treatment/pair membership, refusals and strings at their displayed precision are exact. No relaxed post-hoc tolerance or omitted failure is counted as a pass.', '',
'## Execution and evidence limits', '',
'The permitted Node route was used (Node v24.13.0). Edge launch through the available Playwright driver failed with spawn EPERM; npm installation found no offline cached @playwright/test. The runner executes the page’s shipped inline JavaScript and original shared results-export.js in a VM with a minimal DOM adapter. Statistical functions and rendering functions are unmodified in the original run. There is no independent JavaScript reimplementation of the estimator. The adapter captures generated table/plot markup and actual Blob download contents for JSON, CSV, data Markdown, and both Methods+Results reports.', '',
'This verifies engine results, generated markup, exact strings, serializer consistency, and SVG coordinates. It does **not** verify real DOM parsing/layout, accessibility behavior, browser download UI, chart rasterization, PNG/PDF/JPG files, autosave, navigation/continue-bar interactions, or screenshot fidelity. Markup checks must not be described as live Edge UI evidence. Exported p=NaN versus JSON null was tested explicitly. Metadata timestamps are dynamic; reported statistics are checked independently of them.', '',
'## Faults and changes', '',
f'1. **Normal-tail approximation:** index.html:{anchors["normal_p"]} used a polynomial CDF whose errors exceed the required 1e-9 p tolerance. The patch uses the existing accurate chi-square CDF at z² with one degree of freedom.',
f'2. **Nonexistent indirect evidence:** index.html:{anchors["split_connectivity"]} relied on inversion failure to detect disconnected reduced networks. Roundoff can leave a nonzero pivot in a singular Laplacian, yielding huge or nonfinite indirect SEs. The patch explicitly checks graph reachability.',
f'3. **No-loop global test:** index.html:{anchors["no_loop_dbt"]} returned residual heterogeneity Q and df as the inconsistency test. The patch returns 0/0/undefined and labels the test unavailable. Global Q is also calculated from nested fitted-value differences to avoid subtraction cancellation.',
f'4. **Lost study dependence:** index.html:{anchors["bus_metadata"]} discarded study IDs and full-arm designs during bus conversion. The patch refuses multi-arm bus inputs, preserves optional study IDs for independent two-arm rows, and states the supported scope in the page and README. This prevents false precision; it does not add multi-arm inference.',
f'5. **Stale results and export undefined values:** index.html:{anchors["stale_results"]} retained previous results after invalid input. The patch clears all result state and supplies a reason, including empty/unsupported bus imports. At index.html:{anchors["undefined_export"]}, undefined p was NaN in CSV/Markdown but null in JSON; it is now consistently null/blank on export.',
f'6. **Labels and keys:** index.html:{anchors["parser"]}, {anchors["pair_key"]}, and {anchors["prototype_keys"]} mishandled quoted commas, pipe-delimited pair keys, HTML labels and object-prototype names. The patch parses quoted fields, escapes rendered labels, uses unambiguous pair keys and prototype-free estimate objects.',
f'7. **Clipped CIs:** index.html:{anchors["plot_domain"]} based the plot domain on point estimates alone. The patch includes all direct and indirect confidence limits.', '',
'Before/after examples from saved runs:', '', '| Check | Configuration / quantity | Original | Reference / required | Patched |','|---|---|---:|---:|---:|']
for q in ['split_p','dbt_Q','dbt_df']:
    f=next((f for f in o['failures'] if f['quantity']==q),None)
    if f:
        matching=next((c for c in cs if f['key'].startswith(c['key'])),None);st=patched[matching['key']]['state']
        after=st['dbt'][q[4:]] if q.startswith('dbt_') else next(n['p'] for n in st['nodeSplit'] if f['key']==matching['key']+'::'+n['comparison'])
        L.append(f'| {q} | `{f["key"]}` | {f["got"]} | {f["expected"]} | {after} |')
for diag in read('multiarm-diagnostic.json'):
    st=diag['fits']['true-studies']['dbt'];flat=diag['fits']['flattened']['dbt']
    L.append(f'| Multi-arm global Q/df/p | `{diag["key"]}` | {flat["Q"]:.12g} / {flat["df"]} / {flat["p"]:.12g} | {st["Q"]:.12g} / {st["df"]} / {st["p"]:.12g} | refused: unsupported covariance |')
L+=['','The three multi-arm rows above are actual native-study-versus-flattened netmeta diagnostic runs, not coverage claims for all multi-arm networks. Focused checks also validate shared-bus OR/RR/MD/SMD transformations, zero-cell corrections and small-sample SMD against metafor::escalc; normal p-values against R pnorm; quoted/HTML/pipe/prototype labels; bridge membership; stale-input handling; and empty/unsupported/multi-arm bus refusal.', '', '## Counts by check type', '', '| Type | Original pass/checks | Patched pass/checks |','|---|---:|---:|']
co=category(o);cp=category(p)
for cat in sorted(co):L.append(f'| {cat} | {co[cat]["passed"]}/{co[cat]["checks"]} | {cp[cat]["passed"]}/{cp[cat]["checks"]} |')
L+=['','## Per-quantity results','','| Quantity | Original pass/checks | Patched pass/checks | Original max difference | Patched max difference |','|---|---:|---:|---:|---:|']
for q in sorted(set(o['quantities'])|set(p['quantities'])):
    a=o['quantities'].get(q,dict(passed=0,checks=0,max_difference=0));b=p['quantities'].get(q,dict(passed=0,checks=0,max_difference=0))
    am=f'{a["max_difference"]:.12g}'+(f' ({a["invalid_evidence"]} invalid)' if a.get('invalid_evidence') else '')
    bm=f'{b["max_difference"]:.12g}'+(f' ({b["invalid_evidence"]} invalid)' if b.get('invalid_evidence') else '')
    L.append(f'| {q} | {a["passed"]}/{a["checks"]} | {b["passed"]}/{b["checks"]} | {am} | {bm} |')
L+=['','Exact-check maxima are 0/1 mismatch indicators. Numerical maxima use the specified relative scale, except p-values (absolute). CSV/Markdown numbers are compared exactly to JSON. Plot coordinates use 1e-9 relative; bounds use exact inclusion in the viewBox.', '', '## Reproduction', '',
'On the supplied Windows image, the wrapper locates the requested R installation and libraries relative to the user home/audit tree. For another installation set RSCRIPT, AUDIT_R_LIBS_USER and AUDIT_R_LIBS; set ALLMETA_ROOT for a different source checkout. No installation or network connection is needed. Commands run from the audit directory:', '', '```text','python setup.py','python run_r.py inventory.R','python run_r.py corpus.R','python review_inventory.py','python make_patch.py','node run_app.cjs original','node run_app.cjs patched','python run_r.py reference.R 1 3','python run_r.py reference.R 2 3','python run_r.py reference.R 3 3','python run_r.py diagnose_pm.R','python run_r.py focused.R','python run_r.py bus_reference.R','node test_focused.cjs original','node test_focused.cjs patched','python compare.py original','python compare.py patched','python report.py','python verify_archive.py','```','',
'The three reference commands ran concurrently. They preserve completed keyed results on restart; PM records are reused only when marked with the final uncentered-package-QE oracle. For a clean rerun use a new audit directory and regenerate the inputs. The diagnosis deliberately shows why the earlier centered PM construction is unsuitable. Intermediate partial comparison totals are overwritten; the final logs below are authoritative.', '', 'Verbatim final comparison lines:', '', '```text',Path('comparison-original.txt').read_text().splitlines()[-1],Path('comparison-patched.txt').read_text().splitlines()[-1],f'{fo["passed"]}/{fo["checks"]} focused checks pass (original; Node, not browser)',f'{fp["passed"]}/{fp["checks"]} focused checks pass (patched; Node, not browser)','```','', '## Dataset decisions', '', '| Package | Dataset | Configurations | Decision/reason |','|---|---|---:|---|']
for d in ds:L.append(f'| {d["package"]} | {d["dataset"]} | {d["configurations"]} | {d["reason"].replace("|","/")} |')
Path('RESULTS.md').write_text('\n'.join(L)+'\n',encoding='utf-8')
print(f'Report written: {len(cs)} keys; original {o["passed"]}/{o["checks"]}; patched {p["passed"]}/{p["checks"]}')
